export type ColumnMapping = Record<string, number | undefined>

const norm = (s: string) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9؀-ۿ]+/g, " ").trim()

/** Which file column goes to each field, from the header names; each column is used once. */
export function guessColumns(headers: string[], kind: ImportKind): ColumnMapping {
  const cols = headers.map(norm)
  const taken = new Set<number>()
  const mapping: ColumnMapping = {}
  // exact names first (template headers and aliases), then names that contain the alias
  for (const pass of ["exact", "contains"] as const) {
    for (const field of IMPORT_FIELDS[kind]) {
      if (mapping[field.key] !== undefined) continue
      const names = [field.header, field.key, ...field.aliases].map(norm)
      const i = cols.findIndex((c, idx) => !taken.has(idx) && c !== "" && (pass === "exact" ? names.includes(c) : names.some((n) => n.length > 3 && c.includes(n))))
      if (i >= 0) {
        mapping[field.key] = i
        taken.add(i)
      }
    }
  }
  return mapping
}

/** The template: the headers and one example row. */
export function templateRows(kind: ImportKind): string[][] {
  const fields = IMPORT_FIELDS[kind]
  return [fields.map((f) => f.header), fields.map((f) => f.example)]
}

export type ImportError = "required" | "email" | "number" | "date" | "status" | "source" | "stage" | "role" | "ice" | "percent" | "unknownClient" | "unknownPerson" | "unknownContact" | "duplicate" | "url"

export interface ImportRow {
  /** Line in the file (the header is line 1) */
  line: number
  /** Cell text per field, as read and possibly corrected in the review */
  values: Record<string, string>
  errors: Record<string, ImportError>
  /** Adds a record, or updates the one found (target) */
  action: "create" | "update"
  target?: string
  /** For contacts and deals: the client the row belongs to */
  clientId?: string
}

export interface ImportContext {
  clients: Client[]
  employees: Employee[]
  deals: Deal[]
  /** The company's stages (CRM step 8): their names are accepted in the stage column */
  pipeline?: PipelineSettings
}

/** A stage from a cell: the company's own stage names and ids first, then the usual words for the default stages. */
function readStage(raw: string, pipeline: PipelineSettings = DEFAULT_PIPELINE): DealStageId | undefined | null {
  const v = norm(raw)
  if (!v) return undefined
  const own = pipeline.stages.find((s) => norm(s.id) === v || (s.name && norm(s.name) === v))
  if (own) return own.id
  const word = pick(WORDS.stage, raw)
  // a default stage the company removed is not accepted
  if (word && (isClosedStage(word) || pipeline.stages.some((s) => s.id === word))) return word
  return word === undefined ? undefined : null
}

const WORDS = {
  status: { [ClientStatus.LEAD]: ["lead", "prospect", "potential", "محتمل"], [ClientStatus.ACTIVE]: ["active", "actif", "client", "customer", "نشط"], [ClientStatus.ARCHIVED]: ["archived", "archive", "archivé", "inactive", "inactif", "مؤرشف"] },
  source: {
    [LeadSource.WEBSITE]: ["website", "site", "site web", "web", "seo"],
    [LeadSource.REFERRAL]: ["referral", "recommandation", "parrainage", "bouche a oreille", "word of mouth"],
    [LeadSource.EVENT]: ["event", "événement", "evenement", "salon", "fair", "trade show"],
    [LeadSource.LINKEDIN]: ["linkedin"],
    [LeadSource.OUTREACH]: ["outreach", "prospection", "cold call", "cold email", "démarchage"],
    [LeadSource.PARTNER]: ["partner", "partenaire"],
    [LeadSource.OTHER]: ["other", "autre"],
  },
  stage: {
    [DealStage.LEAD]: ["lead", "new", "nouveau", "prospect"],
    [DealStage.QUALIFIED]: ["qualified", "qualifié", "qualifie"],
    [DealStage.PROPOSAL]: ["proposal", "proposition", "devis", "quote", "offre"],
    [DealStage.NEGOTIATION]: ["negotiation", "négociation", "negociation"],
    [DealStage.WON]: ["won", "gagné", "gagne", "signed", "signé"],
    [DealStage.LOST]: ["lost", "perdu"],
  },
  role: {
    [ContactRole.DECISION_MAKER]: ["decision maker", "decision-maker", "décideur", "decideur", "dg", "ceo", "owner"],
    [ContactRole.FINANCE]: ["finance", "accounting", "comptabilité", "comptabilite", "daf"],
    [ContactRole.TECHNICAL]: ["technical", "technique", "it", "cto"],
    [ContactRole.USER]: ["user", "utilisateur"],
    [ContactRole.OTHER]: ["other", "autre"],
  },
} as const

function pick<T extends string>(table: Record<T, readonly string[]>, raw: string): T | undefined | null {
  const v = norm(raw)
  if (!v) return undefined
  for (const [key, words] of Object.entries(table) as [T, readonly string[]][]) {
    if (norm(key) === v || words.some((w) => norm(w) === v)) return key
  }
  return null
}

const isEmail = (v: string) => /^\S+@\S+\.\S+$/.test(v)
const yes = (v: string) => ["yes", "oui", "true", "1", "x", "y", "o", "نعم", "✓"].includes(norm(v) || v.trim())

/** A date cell: Excel day serials or the usual written forms. */
export function readDate(raw: string) {
  return excelSerialToIso(raw.trim()) ?? parseDate(raw)
}

export function findClient(clients: Client[], ref: string): Client | undefined {
  const v = ref.trim()
  if (!v) return undefined
  const ice = cleanId(v)
  return (
    (ice && /^\d{15}$/.test(ice) ? clients.find((c) => c.ice === ice) : undefined) ??
    clients.find((c) => c.email.toLowerCase() === v.toLowerCase()) ??
    clients.find((c) => norm(c.name) === norm(v) || (c.legalName && norm(c.legalName) === norm(v)))
  )
}

export function findPerson(employees: Employee[], ref: string): Employee | undefined {
  const v = ref.trim().toLowerCase()
  return v ? employees.find((e) => e.email.toLowerCase() === v || e.name.toLowerCase() === v) : undefined
}

/** Reads the file rows into checked import rows. */
export function readRows(table: string[][], mapping: ColumnMapping, kind: ImportKind, ctx: ImportContext): ImportRow[] {
  const fields = IMPORT_FIELDS[kind]
  const rows = table.slice(0, MAX_IMPORT_ROWS).map((cells, i) => {
    const values: Record<string, string> = {}
    for (const f of fields) {
      const col = mapping[f.key]
      values[f.key] = col === undefined ? "" : (cells[col] ?? "").trim()
    }
    return { line: i + 2, values }
  })
  return checkRows(rows, kind, ctx)
}

/** Checks rows again (after a correction in the review), including duplicates inside the file. */
export function checkRows(rows: { line: number; values: Record<string, string> }[], kind: ImportKind, ctx: ImportContext): ImportRow[] {
  const seen = new Set<string>()
  return rows.map(({ line, values }) => {
    const row = checkRow(line, values, kind, ctx)
    const keys = duplicateKeys(row, kind)
    const dup = keys.find((k) => seen.has(k))
    if (dup) row.errors[kind === "deals" ? "title" : kind === "contacts" ? "email" : dup.startsWith("ice:") ? "ice" : dup.startsWith("email:") ? "email" : "name"] = "duplicate"
    keys.forEach((k) => seen.add(k))
    return row
  })
}

/** What makes two rows the same record: a client's ICE or e-mail (or name when it has neither). */
function duplicateKeys(row: ImportRow, kind: ImportKind): string[] {
  const v = row.values
  if (kind === "clients") {
    const ice = cleanId(v.ice)
    const keys = [ice ? `ice:${ice}` : "", v.email ? `email:${v.email.toLowerCase()}` : ""].filter(Boolean)
    return keys.length ? keys : v.name ? [`name:${norm(v.name)}`] : []
  }
  if (kind === "contacts") return row.clientId && v.email ? [`${row.clientId}|${v.email.toLowerCase()}`] : []
  return row.clientId && v.title ? [`${row.clientId}|${norm(v.title)}`] : []
}

function checkRow(line: number, values: Record<string, string>, kind: ImportKind, ctx: ImportContext): ImportRow {
  const errors: Record<string, ImportError> = {}
  for (const f of IMPORT_FIELDS[kind]) if (f.required && !values[f.key]) errors[f.key] = "required"
  const v = values

  if (kind === "clients") {
    if (v.email && !isEmail(v.email)) errors.email = "email"
    if (v.contactEmail && !isEmail(v.contactEmail)) errors.contactEmail = "email"
    if (v.website && !isWebUrl(v.website)) errors.website = "url"
    if (v.status && pick(WORDS.status, v.status) === null) errors.status = "status"
    if (v.leadSource && pick(WORDS.source, v.leadSource) === null) errors.leadSource = "source"
    if (v.ice && !/^\d{15}$/.test(cleanId(v.ice) ?? "")) errors.ice = "ice"
    if (v.paymentTermsDays && !(Number(v.paymentTermsDays) >= 0 && Number.isInteger(Number(v.paymentTermsDays)))) errors.paymentTermsDays = "number"
    if (v.accountManager && !findPerson(ctx.employees, v.accountManager)) errors.accountManager = "unknownPerson"
    const ice = cleanId(v.ice)
    const existing = (ice ? ctx.clients.find((c) => c.ice === ice) : undefined) ?? (v.email ? ctx.clients.find((c) => c.email.toLowerCase() === v.email!.toLowerCase()) : undefined)
    // a client found by its ICE or e-mail keeps its name when the cell is empty
    if (existing && errors.name === "required") delete errors.name
    return { line, values, errors, action: existing ? "update" : "create", target: existing?.id }
  }

  const client = v.client ? findClient(ctx.clients, v.client) : undefined
  if (v.client && !client) errors.client = "unknownClient"

  if (kind === "contacts") {
    if (v.email && !isEmail(v.email)) errors.email = "email"
    if (v.role && pick(WORDS.role, v.role) === null) errors.role = "role"
    if (v.linkedin && !isWebUrl(v.linkedin)) errors.linkedin = "url"
    const existing = client && v.email ? client.contacts.find((c) => c.email.toLowerCase() === v.email!.toLowerCase()) : undefined
    return { line, values, errors, action: existing ? "update" : "create", target: existing?.id, clientId: client?.id }
  }

  if (v.amount && !(parseAmount(v.amount) >= 0)) errors.amount = "number"
  if (v.expectedClose && !readDate(v.expectedClose)) errors.expectedClose = "date"
  if (v.stage && readStage(v.stage, ctx.pipeline) === null) errors.stage = "stage"
  if (v.probability) {
    const p = Number(v.probability.replace("%", "").trim())
    if (!(p >= 0 && p <= 100)) errors.probability = "percent"
  }
  if (v.owner && !findPerson(ctx.employees, v.owner)) errors.owner = "unknownPerson"
  if (v.contact && client && !contactIn(client, v.contact)) errors.contact = "unknownContact"
  const existing = client && v.title ? ctx.deals.find((d) => d.clientId === client.id && norm(d.title) === norm(v.title!)) : undefined
  return { line, values, errors, action: existing ? "update" : "create", target: existing?.id, clientId: client?.id }
}

const contactIn = (client: Client, ref: string) => client.contacts.find((c) => c.email.toLowerCase() === ref.trim().toLowerCase() || norm(c.name) === norm(ref))

export const hasErrors = (row: ImportRow) => Object.keys(row.errors).length > 0

// ---------- What a checked row saves ----------

const tagsOf = (raw: string) => raw.split(/[;,|]/).map((t) => t.trim()).filter(Boolean)

/** The client fields a clients row sets; empty cells leave the current value alone. */
export function clientFields(row: ImportRow, ctx: ImportContext) {
  const v = row.values
  const out: Record<string, unknown> = {}
  const set = (key: string, value: unknown) => {
    if (value !== undefined && value !== "") out[key] = value
  }
  set("name", v.name)
  set("email", v.email?.toLowerCase())
  set("phone", v.phone)
  set("industry", v.industry)
  set("status", pick(WORDS.status, v.status ?? "") ?? undefined)
  set("legalName", v.legalName)
  set("ice", cleanId(v.ice))
  set("taxId", v.taxId)
  set("address", v.address)
  set("country", v.country?.toUpperCase())
  set("website", v.website)
  set("paymentTermsDays", v.paymentTermsDays ? Number(v.paymentTermsDays) : undefined)
  set("accountManagerId", v.accountManager ? findPerson(ctx.employees, v.accountManager)?.id : undefined)
  set("leadSource", pick(WORDS.source, v.leadSource ?? "") ?? undefined)
  set("tags", v.tags ? tagsOf(v.tags) : undefined)
  set("notes", v.notes)
  return out
}

export function contactFields(row: ImportRow) {
  const v = row.values
  return {
    name: v.name ?? "",
    email: (v.email ?? "").toLowerCase(),
    phone: v.phone || undefined,
    position: v.position || undefined,
    role: pick(WORDS.role, v.role ?? "") ?? undefined,
    linkedin: v.linkedin || undefined,
    isPrimary: v.isPrimary ? yes(v.isPrimary) : undefined,
  }
}

export function dealFields(row: ImportRow, ctx: ImportContext) {
  const v = row.values
  const client = ctx.clients.find((c) => c.id === row.clientId)
  return {
    title: v.title ?? "",
    amount: parseAmount(v.amount ?? ""),
    expectedClose: readDate(v.expectedClose ?? ""),
    stage: readStage(v.stage ?? "", ctx.pipeline) ?? undefined,
    probability: v.probability ? Number(v.probability.replace("%", "").trim()) : undefined,
    ownerId: v.owner ? findPerson(ctx.employees, v.owner)?.id : undefined,
    contactId: client && v.contact ? contactIn(client, v.contact)?.id : undefined,
    note: v.note || undefined,
  }
}
